public class Main {
    record Key(int h) {
        @Override
        public int hashCode() { return h; }
    }
    static int bucket(Object k, int n) {
        return Math.abs(k.hashCode()) % n;
    }
    public static void main(String[] args) {
        String[] buckets = new String[10];
        Key k = new Key(Integer.MIN_VALUE);
        int b = bucket(k, buckets.length);
        System.out.println("bucket " + b);
        buckets[b] = "x";
    }
}

