public class Main {
    static int toInt(String s) {
        int v = 0;
        for (char c : s.toCharArray()) {
            if (c < '0' || c > '9') {
                throw new IllegalArgumentException(s);
            }
            v = v * 10 + (c - '0');
        }
        return v;
