public class Main {
    static String preview(String s, int n) {
        if (s.codePointCount(0, s.length()) <= n) return s;
        return s.substring(0, s.offsetByCodePoints(0, n));
    }
    public static void main(String[] args) {
        String msg = "Hi \uD83D\uDE00";
        String p = preview(msg, 4);
        System.out.println(msg.length());
        System.out.println(p.length());
        char last = p.charAt(p.length() - 1);
        System.out.println(Character.isHighSurrogate(last));
    }
}
